`mergeIntervals(intervals)` accepts an array of two-element arrays containing finite numbers `[start, end]`, with `start <= end`. It returns newly allocated intervals sorted by ascending start and then ascending end. Overlapping or touching intervals must be merged. An empty array returns an empty array. Malformed input throws `TypeError`.

The function must not mutate the outer input array, any inner interval, or retain aliases to an inner interval. Use CommonJS and export exactly `{ mergeIntervals }` with `module.exports`.

Known-bad source:
```javascript
'use strict';

function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }
  for (const interval of intervals) {
    if (
      !Array.isArray(interval) ||
      interval.length !== 2 ||
      !interval.every((value) => typeof value === 'number' && Number.isFinite(value)) ||
      interval[0] > interval[1]
    ) {
      throw new TypeError('invalid interval');
    }
  }
  if (intervals.length === 0) {
    return [];
  }

  const sorted = intervals.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const result = [];
  let current = sorted[0].slice();

  for (let index = 1; index < sorted.length; index += 1) {
    const next = sorted[index];
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      result.push(current);
      current = next.slice();
    }
  }
  result.push(current);
  return result;
}

module.exports = { mergeIntervals };
```

