'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['mergeIntervals']);
assert.strictEqual(typeof api.mergeIntervals, 'function');
const { mergeIntervals } = api;

assert.deepStrictEqual(mergeIntervals([]), []);

const intervals = [[5, 7], [1, 2], [2, 4], [10, 10], [8, 10], [20, 21], [20, 20]];
const snapshot = intervals.map((interval) => interval.slice());
const result = mergeIntervals(intervals);
assert.deepStrictEqual(result, [[1, 4], [5, 7], [8, 10], [20, 21]]);
assert.deepStrictEqual(intervals, snapshot);
assert.notStrictEqual(result, intervals);
for (const outputInterval of result) {
  for (const inputInterval of intervals) {
    assert.notStrictEqual(outputInterval, inputInterval);
  }
}

const isolated = [[3, 3], [-2, -1]];
const isolatedResult = mergeIntervals(isolated);
assert.deepStrictEqual(isolatedResult, [[-2, -1], [3, 3]]);
assert.notStrictEqual(isolatedResult[0], isolated[1]);
assert.notStrictEqual(isolatedResult[1], isolated[0]);

assert.deepStrictEqual(
  mergeIntervals([[1, 10], [2, 3], [4, 12], [12, 15]]),
  [[1, 15]]
);

for (const invalid of [
  null,
  {},
  [1, 2],
  [[1]],
  [[1, 2, 3]],
  [['1', 2]],
  [[NaN, 2]],
  [[1, Infinity]],
  [[2, 1]],
  [[0, 1], null]
]) {
  assert.throws(() => mergeIntervals(invalid), TypeError);
}

